import{c as e,Q as l,j as a,m as _}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"约束说明","description":"","frontmatter":{},"headers":[{"level":1,"title":"约束说明","slug":"约束说明"}],"relativePath":"guide/编程指南/编译与运行/算子编译/约束说明.md","filePath":"guide/编程指南/编译与运行/算子编译/约束说明.md"}'),s={name:"guide/编程指南/编译与运行/算子编译/约束说明.md"};function n(p,t,i,r,o,c){return l(),a("div",null,[...t[0]||(t[0]=[_(`<h1 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h1><ul><li><p>在同一个编译单元，若存在多个核函数，暂不支持自动推导Kernel类型，需要开发者手动设置Kernel类型。</p><ul><li>特别地，针对如下型号，无论是否是同一个编译单元多个核函数的场景，均不支持在开发者未设置Kernel类型时进行自动推导。建议开发者手动设置Kernel类型。 <ul><li>Ascend 950PR/Ascend 950DT</li><li>Atlas 推理系列产品 &lt;/br&gt;</li></ul></li></ul></li><li><p>Kernel函数推荐使用 __cube__ / __vector__ / __mix__(cube, vec) 进行标记，KERNEL_TASK_TYPE_DEFAULT接口即将废弃。 &lt;/br&gt;</p></li><li><p>纯Scalar算子无法实现自动推导 需手动标记Kernel函数类型，推荐设置为纯Vector类型，添加__vector__ attribute进行标记：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__global__ __vector__ __aicore__ void func0(__gm__ uint8* Addr) {</span></span>
<span class="line"><span>    Addr[1] = Addr[0];</span></span>
<span class="line"><span>    AscendC::printf(&quot;Hello world&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div></li></ul><p>&lt;/br&gt;</p><ul><li><p>bfloat16_t等数据类型在 Host 端仅支持以 C++ 模板的形式进行定义与声明，具体数据类型如下：</p><p><strong>Ascend 950PR/Ascend 950DT</strong>：bfloat16_t、hifloat8_t、fp8_e5m2_t、fp8_e4m3fn_t、fp8_e8m0_t、fp4x2_e2m1_t、fp4x2_e1m2_t、int4x2_t。</p><p><strong>Atlas A2 训练系列产品/Atlas A2 推理系列产品</strong>：bfloat16_t。</p><p><strong>Atlas A3 训练系列产品/Atlas A3 推理系列产品</strong>：bfloat16_t。</p></li></ul>`,4)])])}const f=e(s,[["render",n]]);export{u as __pageData,f as default};
